// src/generator/assetRegistry.ts
async function generateAssetTypes(args, emitters) {
  const resolved = emitters ?? resolveRegistryEmitters(["typescript"], {
    defaultOutputPath: args.outputPath,
    gameRoot: process.cwd()
  });
  const manifest = buildAssetManifest(args);
  if (args.manifestPath !== void 0) {
    await fse2.outputFile(
      args.manifestPath,
      JSON.stringify(manifest, null, 2) + "\n"
    );
  }
  for (const { emitter, outputPath } of resolved) {
    await emitter.emit({
      manifest,
      manifestPath: args.manifestPath,
      outputPath
    });
  }
  const animationCount = manifest.models.reduce(
    (acc, m) => acc + m.animations.length,
    0
  );
  const dataIdCount = manifest.data.reduce((acc, d) => acc + d.ids.length, 0);
  const audioIdCount = manifest.audio.sfx.length + manifest.audio.music.length + manifest.audio.environment.length;
  const navMeshTileCount = manifest.navmesh.reduce(
    (acc, nm) => acc + nm.manifest.tiles.length,
    0
  );
  const tileCacheCellCount = manifest.tileCache.reduce(
    (acc, tc) => acc + tc.manifest.tiles.length,
    0
  );
  info(
    `Types: wrote ${manifest.sprites.length} sprite id${manifest.sprites.length === 1 ? "" : "s"} + ${manifest.ui.length} ui id${manifest.ui.length === 1 ? "" : "s"} + ${manifest.models.length} model id${manifest.models.length === 1 ? "" : "s"} (${animationCount} animation${animationCount === 1 ? "" : "s"}) + ${manifest.data.length} data domain${manifest.data.length === 1 ? "" : "s"} (${dataIdCount} record${dataIdCount === 1 ? "" : "s"}) + ${audioIdCount} audio id${audioIdCount === 1 ? "" : "s"} + ${manifest.navmesh.length} navmesh world${manifest.navmesh.length === 1 ? "" : "s"} (${navMeshTileCount} tile${navMeshTileCount === 1 ? "" : "s"}) + ${manifest.tileCache.length} tilecache world${manifest.tileCache.length === 1 ? "" : "s"} (${tileCacheCellCount} cell${tileCacheCellCount === 1 ? "" : "s"}) + ${manifest.locales.length} locale${manifest.locales.length === 1 ? "" : "s"} (${manifest.translationKeys.length} translation key${manifest.translationKeys.length === 1 ? "" : "s"}) \u2192 ${relative(process.cwd(), args.outputPath)}`
  );
}

// src/target/resolveTarget.ts
import { join } from "path";
import fse3 from "fs-extra";
import { resolveGameTarget } from "@unsupervised/schemas";
function targetDescriptorPath(rootDir) {
  return join(rootDir, ".atelier", "target.json");
}
async function resolveTargetForRoot(rootDir) {
  const path = targetDescriptorPath(rootDir);
  if (!await fse3.pathExists(path)) {
    return resolveGameTarget(null);
  }
  const raw = await fse3.readJson(path);
  return resolveGameTarget(raw);
}

// src/pipelines/audioPipeline.ts
import { extname as extname2, join as join2, posix, relative as relative2, sep } from "path";
import fse4 from "fs-extra";
import ffmpeg from "fluent-ffmpeg";
import { glob } from "glob";

// src/utils/identifier.ts
import { extname } from "path";
var REPLACE_PATTERN = /[\s\-./\\]+/g;
var INVALID_CHAR_PATTERN = /[^a-zA-Z0-9_]/g;
